update public.partner_workspace set state=jsonb_set(jsonb_set(jsonb_set(state,'{draft}',(state->'draft') || '{"pages":[{"slug":"/","title":"Your artistry. | OLREADY","description":"Discover the network. Explore artist stories. Find your plan.","eyebrow":"For makeup artists, by people who get it","heading":"Your artistry.","accent":"Backed by OLREADY.","body":"You create the looks. We help you explore the opportunities. Discover OLREADY, meet our artists and find your plan.","primaryLabel":"Explore artist results","primaryHref":"/top-grossing-artists","secondaryLabel":"Compare plans","secondaryHref":"/plans","sections":[{"id":"home-story","title":"Your artistry deserves opportunity.","body":"From bridal looks to occasion makeup, your portfolio tells your story. Give prospective clients a clear view of your work, then choose the enquiry access that fits your business.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"home-plans","title":"Three plans. Your next step.","body":"Pro brings 60 verified enquiries and three months of access across three states. Phoenix and invite-only Privy offer six months of access with pan-India reach. Compare the details and speak to our team.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"home-process","title":"Your profile is where it begins.","body":"Create or complete your artist profile on the OLREADY merchant website. Add your work, review your details and connect with our team to discuss the right plan.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"}]},{"slug":"/benefits","title":"Built around your artistry. | OLREADY","description":"Understand how OLREADY fits into your business before you choose a plan.","eyebrow":"More clarity. Better decisions.","heading":"More reach. More possibilities.","accent":"","body":"Bring your artistry to the conversation. Choose enquiry access, geography and support around the way you want to grow.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[{"id":"enquiries","title":"Opportunities to start a conversation.","body":"Pro includes 60 verified enquiries. Phoenix includes 100 verified leads, and Privy includes 120. Use the conversation to understand the client’s brief, share your portfolio and discuss availability.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"reach","title":"Choose how far you want to go.","body":"Pro provides access across three states. Phoenix and Privy provide pan-India access. Discuss the locations you serve with the team before choosing.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"support","title":"A relationship manager, when your plan includes one.","body":"Phoenix and Privy include a dedicated relationship manager. For questions about any plan or your artist profile, the OLREADY team is available on WhatsApp.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"reversal","title":"Clarity on lead reversal.","body":"Phoenix and Privy include lead reversal. Ask the team for the eligibility conditions and process before purchasing; the brochure does not specify them.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"portfolio","title":"Let your work introduce you.","body":"Complete your merchant profile with your portfolio and accurate service details. Keep your availability and client conversations up to date.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"}]},{"slug":"/top-grossing-artists","title":"Top Grossing Artists | OLREADY","description":"Discover individual artist results and selected video stories.","eyebrow":"The people behind the numbers","heading":"Top Grossing Artists","accent":"","body":"Explore featured artist results and hear selected artists describe their experience in their own words.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[{"id":"results-context","title":"Understand the story behind the figure.","body":"Every published result is shown with its reporting period and what the figure measures. Individual outcomes differ; use these stories to ask better questions about the opportunity for your own business.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"}]},{"slug":"/how-it-works","title":"Your next chapter starts here. | OLREADY","description":"A simple path from exploring OLREADY to completing your artist profile.","eyebrow":"How it works","heading":"Your next chapter starts here.","accent":"","body":"Explore the opportunity. Find your plan. Build your artist profile.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[{"id":"step-one","title":"01 / See what fits your business.","body":"Explore the benefits and artist stories. Consider the locations you serve, the clients you want to reach and the support you need.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"step-two","title":"02 / Compare your options.","body":"Review Pro at ₹18,999, Phoenix at ₹35,000 and invite-only Privy at ₹50,000. Compare enquiry allowances, duration and geographical access.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"step-three","title":"03 / Talk through the details.","body":"Ask our team about taxes, plan terms and any applicable offers. For Privy, request an invitation and the written conditions of the assured-business offer.","eyebrow":"","image":"","button":"Compare plans","href":"/plans"},{"id":"step-four","title":"04 / Make your profile yours.","body":"Use the OLREADY merchant website to create or log in to your artist profile. Add your portfolio and check your business details. Our team can help with your next steps.","eyebrow":"","image":"","button":"Create your profile","href":"https://merchant.olready.in/makeup/login"}]},{"slug":"/plans","title":"A plan for your next move. | OLREADY","description":"Compare the options. Understand the details. Choose with confidence.","eyebrow":"Pro / Phoenix / Privy","heading":"Choose how far your artistry goes.","accent":"","body":"More reach. More opportunities. Compare Pro, Phoenix and Privy, and choose your next step with clarity.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[]},{"slug":"/checkout","title":"Review your plan. | OLREADY","description":"A clear summary of your plan and contact details.","eyebrow":"Your selection","heading":"Review your plan.","accent":"","body":"Review your selection and leave your contact details. Our team can help with the next step. No payment is taken here yet.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[]},{"slug":"/help","title":"Let’s clear things up. | OLREADY","description":"Straightforward answers before you take the next step.","eyebrow":"We are here to help","heading":"Good questions. Clear next steps.","accent":"","body":"Find the details on plans, profiles and support—or talk to the team about your business.","primaryLabel":"Compare plans","primaryHref":"/plans","secondaryLabel":"Talk to the team","secondaryHref":"/help","sections":[]}],"plans":[{"id":"pro","name":"Pro","tagline":"Best seller","description":"More reach. More opportunities. More time to convert.","pricePaise":1899900,"term":"3 months access","taxPercent":0,"features":["60 verified enquiries","3 months access","3-state access"],"exclusions":"Confirm enquiry eligibility and applicable plan conditions with the team before purchasing.","geography":"Access across 3 states. Confirm your selected states with the team.","leadModel":"60 verified enquiries during the plan. An enquiry is not a confirmed booking.","renewal":"Ask the team for current renewal prici